INSERT INTO `resume_template` VALUES (3, 'timeline', '时间轴', '紫色分区标题，模块之间留白充足，适合项目经历较多的人', '', 1, '{\"style\": {\"themeColor\": \"#6d28d9\", \"textFontColor\": \"#5b6b82\", \"textFontWeight\": 400, \"secondTitleColor\": \"#4c1d95\", \"modelMarginBottom\": \"42px\", \"secondTitleWeight\": 600, \"firstTitleFontSize\": \"21px\"}, \"layout\": \"classical\", \"variants\": {\"AWARDS\": \"AWARDS_8\", \"HOBBIES\": \"HOBBIES_8\", \"JOB_INTENTION\": \"JOB_INTENTION_8\", \"WORKS_DISPLAY\": \"WORKS_DISPLAY_8\", \"EDU_BACKGROUND\": \"EDU_BACKGROUND_8\", \"SELF_EVALUATION\": \"SELF_EVALUATION_8\", \"WORK_EXPERIENCE\": \"WORK_EXPERIENCE_8\", \"CAMPUS_EXPERIENCE\": \"CAMPUS_EXPERIENCE_8\", \"SKILL_SPECIALTIES\": \"SKILL_SPECIALTIES_10\", \"PROJECT_EXPERIENCE\": \"PROJECT_EXPERIENCE_8\", \"INTERNSHIP_EXPERIENCE\": \"INTERNSHIP_EXPERIENCE_8\"}}', 1, 0, '2026-09-25 18:24:47', '2026-09-25 18:24:47', 1, 1, 1790331887000);

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user`  (
  `uid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户ID',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '昵称',
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '账号',
  `password` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '密码',
  `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '邮箱',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '头像',
  `openid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'openid',
  `ch` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '渠道',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `status` tinyint NOT NULL COMMENT '状态',
  `ver` int NOT NULL COMMENT '版本号',
  `is_delete` bigint NOT NULL COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uniq_user_username_ch`(`username` ASC, `ch` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户表' ROW_FORMAT = DYNAMIC;

